#include <stdlib.h>
#include <string.h>
#include <float.h>

// O(n^3) Hungarian (shortest augmenting path) for min-cost assignment.
// cost: n x n row-major double array. Returns assignment in 'assign' (assign[i] = column for row i).
void hungarian(int n, const double *cost, int *assign) {
    double *u = (double*)calloc(n+1, sizeof(double));
    double *v = (double*)calloc(n+1, sizeof(double));
    int *p = (int*)calloc(n+1, sizeof(int));
    int *way = (int*)calloc(n+1, sizeof(int));
    double *minv = (double*)malloc((n+1)*sizeof(double));
    char *used = (char*)calloc(n+1, sizeof(char));
    const double INF = DBL_MAX/4;

    for (int i = 1; i <= n; i++) {
        p[0] = i;
        int j0 = 0;
        for (int j = 0; j <= n; j++) { minv[j] = INF; used[j] = 0; }
        while (1) {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = INF;
            int j1 = -1;
            const double *crow = cost + (i0-1)*n;
            for (int j = 1; j <= n; j++) {
                if (!used[j]) {
                    double cur = crow[j-1] - u[i0] - v[j];
                    if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                    if (minv[j] < delta) { delta = minv[j]; j1 = j; }
                }
            }
            for (int j = 0; j <= n; j++) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else minv[j] -= delta;
            }
            j0 = j1;
            if (p[j0] == 0) break;
        }
        while (1) {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
            if (j0 == 0) break;
        }
    }
    for (int j = 1; j <= n; j++) assign[p[j]-1] = j-1;
    free(u); free(v); free(p); free(way); free(minv); free(used);
}
